<?php defined('ABSPATH')||exit; function bluprint_footer_register_settings(){ register_setting('bluprint_footer_group','bluprint_footer_title',['sanitize_callback'=>'sanitize_textarea_field']); register_setting('bluprint_footer_group','bluprint_footer_description',['sanitize_callback'=>'sanitize_textarea_field']); register_setting('bluprint_footer_group','bluprint_footer_image',['sanitize_callback'=>'absint']); register_setting('bluprint_footer_group','bluprint_footer_menu_title_1',['sanitize_callback'=>'sanitize_text_field']); register_setting('bluprint_footer_group','bluprint_footer_menu_title_2',['sanitize_callback'=>'sanitize_text_field']); }
add_action('admin_init','bluprint_footer_register_settings'); function bluprint_footer_admin_menu(){ add_submenu_page('bluprint-settings','تنظیمات فوتر','تنظیمات فوتر','edit_theme_options','bluprint-footer','bluprint_footer_settings_page'); }
add_action('admin_menu','bluprint_footer_admin_menu'); function bluprint_footer_admin_assets($hook){ if(!bluprint_is_admin_page('bluprint-footer'))return; wp_enqueue_media(); wp_enqueue_script( 'bluprint-footer-admin', get_theme_file_uri('inc/footer-admin.js'), ['jquery'], bluprint_asset_version('inc/footer-admin.js'), true ); }
add_action('admin_enqueue_scripts','bluprint_footer_admin_assets'); function bluprint_footer_settings_page(){ if(!current_user_can('edit_theme_options'))return; $title=get_option('bluprint_footer_title','ایده‌های بزرگ از جزئیات دقیق شروع می‌شوند.'); $description=get_option('bluprint_footer_description',''); $menu_title_1=get_option('bluprint_footer_menu_title_1','دسترسی سریع'); $menu_title_2=get_option('bluprint_footer_menu_title_2','اطلاعات بیشتر'); $image_id=absint(get_option('bluprint_footer_image')); $image_url=$image_id?wp_get_attachment_image_url($image_id,'large'):''; ?> <div class="wrap"> <h1>تنظیمات فوتر</h1> <form method="post" action="options.php"> <?php settings_fields('bluprint_footer_group'); ?> <table class="form-table"> <tr> <th> <label for="bluprint_footer_title">عنوان اصلی فوتر</label> </th> <td> <textarea id="bluprint_footer_title" name="bluprint_footer_title" rows="4" class="large-text" ><?php echo esc_textarea($title); ?></textarea> </td> </tr> <tr> <th> <label for="bluprint_footer_description">توضیحات فوتر</label> </th> <td> <textarea id="bluprint_footer_description" name="bluprint_footer_description" rows="6" class="large-text" ><?php echo esc_textarea($description); ?></textarea> <p class="description">فاصله‌ها و شکست خطوط متن در سایت حفظ می‌شوند.</p> </td> </tr> <tr> <th> <label for="bluprint_footer_menu_title_1">عنوان منوی اول</label> </th> <td> <input type="text" id="bluprint_footer_menu_title_1" name="bluprint_footer_menu_title_1" class="regular-text" value="<?php echo esc_attr($menu_title_1); ?>" > </td> </tr> <tr> <th> <label for="bluprint_footer_menu_title_2">عنوان منوی دوم</label> </th> <td> <input type="text" id="bluprint_footer_menu_title_2" name="bluprint_footer_menu_title_2" class="regular-text" value="<?php echo esc_attr($menu_title_2); ?>" > </td> </tr> <tr> <th>تصویر فوتر</th> <td> <input type="hidden" id="bluprint_footer_image" name="bluprint_footer_image" value="<?php echo esc_attr($image_id); ?>" > <div id="bluprint-footer-preview"> <?php if($image_url): ?> <img src="<?php echo esc_url($image_url); ?>" style="max-width:320px;height:auto" alt="" > <?php endif; ?> </div> <button type="button" class="button" id="bluprint-footer-select"> انتخاب تصویر </button> <button type="button" class="button" id="bluprint-footer-remove"> حذف تصویر انتخاب‌شده </button> </td> </tr> </table> <?php submit_button('ذخیره تنظیمات'); ?> </form> </div> <?php }
function bluprint_footer_title(){ return get_option('bluprint_footer_title','ایده‌های بزرگ از جزئیات دقیق شروع می‌شوند.'); }
function bluprint_footer_description(){ return get_option('bluprint_footer_description',''); }
function bluprint_footer_menu_title($index){ $defaults=[ 1=>'دسترسی سریع', 2=>'اطلاعات بیشتر' ]; $index=(int)$index; if(!isset($defaults[$index]))return ''; return get_option('bluprint_footer_menu_title_'.$index,$defaults[$index]); }
function bluprint_footer_image(){ $id=absint(get_option('bluprint_footer_image')); if($id){ $image=wp_get_attachment_image($id,'large',false,[ 'class'=>'site-footer__artwork', 'alt'=>'', 'loading'=>'lazy', 'decoding'=>'async' ]); if($image)return $image; } return '<img class="site-footer__artwork" src="'.esc_url(get_theme_file_uri('assets/images/footer-artwork.png')).'" alt="" loading="lazy" decoding="async">'; }